    def test_create_jobs_loopback_http_roundtrip(self):
        """Execute create_jobs end-to-end over real TCP loopback HTTP."""
        import types as _types
        from examples.mock_x_api_server import MockResponse
        from xdk.streaming import StreamConfig
        self.loopback_server.reset()
        full_mock_json = '{"data":{"created_at":"test_value","download_expires_at":"test_value","download_url":"test_value","id":"1234567890","name":"test_value","resumable":true,"status":"test_value","type":"test_value","upload_expires_at":"test_value","upload_url":"test_value"}}'
        self.loopback_server.set_responder(
            lambda _req: MockResponse.json(
                200,
                full_mock_json,
            )
        )
        kwargs = {}
        from xdk.compliance.models import CreateJobsRequest
        try:
            CreateJobsRequest.model_rebuild()
        except Exception:
            pass
        req_json_str = '{"name":"test_value","resumable":true,"type":"tweets"}'
        try:
            kwargs["body"] = CreateJobsRequest.model_validate_json(req_json_str)
        except Exception:
            kwargs["body"] = CreateJobsRequest.model_construct(
                **json.loads(req_json_str)
            )
        method = getattr(self.loopback_compliance_client, "create_jobs")
        result = method(**kwargs)
        if isinstance(result, _types.GeneratorType):
            first_item = next(result)
